import sys

def count_distinct_prime_factors(n):
    if n <= 1:
        return 0
    count = 0
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count += 1
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        count += 1
    return count

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        S = []
        for _ in range(N):
            S.append(int(next(iterator)))
    except StopIteration:
        return

    # Precompute sum and revenue for every subset mask
    num_masks = 1 << N
    subset_sum = [0] * num_masks
    subset_revenue = [0] * num_masks

    for mask in range(1, num_masks):
        current_sum = 0
        for i in range(N):
            if mask & (1 << i):
                current_sum += S[i]
        subset_sum[mask] = current_sum
        subset_revenue[mask] = count_distinct_prime_factors(current_sum)

    # DP: dp[mask] = max revenue to sell exactly the items in 'mask'
    dp = [0] * num_masks

    # Iterate through all masks
    for mask in range(1, num_masks):
        # Try to form this mask by adding a non-empty submask 'sub' to a previous state 'prev'
        # Optimization: iterate over submasks of 'mask'
        sub = mask
        while sub > 0:
            prev = mask ^ sub
            # If prev is 0, it means we are forming the mask entirely from 'sub'
            # Otherwise, we combine revenue of 'prev' and 'sub'
            current_val = subset_revenue[sub]
            if prev != 0:
                current_val += dp[prev]
            if current_val > dp[mask]:
                dp[mask] = current_val

            # Move to next submask: sub = (sub - 1) & mask
            sub = (sub - 1) & mask

    print(dp[num_masks - 1])

if __name__ == "__main__":
    solve()
